from datetime import date
from typing import Dict, List, Tuple

class Loyalty:
    def __init__(self) -> None:
        # Store purchases as {customer: [(amount, day), ...]}
        self.purchases: Dict[str, List[Tuple[float, date]]] = {}
        # Store redemptions as {customer: [(points, day), ...]}
        self.redemptions: Dict[str, List[Tuple[int, date]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        # Calculate points: 1 point for every full $10.00 spent
        points = int(amount // 10.0)

        # Store the purchase
        if customer not in self.purchases:
            self.purchases[customer] = []
        self.purchases[customer].append((amount, day))

        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        # Calculate total points earned from purchases on or before the given day
        total_earned = 0
        if customer in self.purchases:
            for amount, purchase_day in self.purchases[customer]:
                if purchase_day <= day:
                    total_earned += int(amount // 10.0)

        # Calculate total points redeemed on or before the given day
        total_redeemed = 0
        if customer in self.redemptions:
            for points, redemption_day in self.redemptions[customer]:
                if redemption_day <= day:
                    total_redeemed += points

        return total_earned - total_redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points for a customer on a given day."""
        # Check if points is a multiple of 100
        if points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100")

        # Check if enough points are available
        available_balance = self.balance(customer, day)
        if points > available_balance:
            raise ValueError("Not enough points available for redemption")

        # Record the redemption
        if customer not in self.redemptions:
            self.redemptions[customer] = []
        self.redemptions[customer].append((points, day))
